SELECT p.discharge_location, p.deathtime, percentile_cont(0.75) within GROUP (ORDER BY (p.dischtime - p.admittime)) - percentile_cont(0.25) within GROUP (ORDER BY (p.dischtime - p.admittime)) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age = 82 AND a.admission_type = 'E' AND p.anchor_year BETWEEN 77 AND 87 GROUP BY p.discharge_location, p.deathtime ORDER BY interquartile_range NULLS LAST;